pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos) public {
        vm.assume(_tos.length > 0);
        // Deploy a callee that reverts on any call to mimic a failing external party.
        Reverter callee = new Reverter();
        bool ok;
        try c.transfer(address(this), address(callee), _tos, 0) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference C returns true (ok==true) for any non-empty _tos.
        // Buggy C with require(false) always reverts (ok==false).
        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        // Deploy a helper contract that will be the caddress target; it must have code so low-level call can fail or succeed.
        Helper helper = new Helper();
        // The reference succeeds (returns true) for any helper that does not revert in transferFrom;
        // the mutant reverts before any call, so we catch the revert.
        bool ok;
        try c.transfer(from, address(helper), _tos, v) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Helper {
    // To allow caddress.call(transferFrom) to succeed, implement fallback that returns true.
    fallback() external payable returns (bool) {
        return true;
    }
}

